package com.bank.capacity.service;

import com.bank.capacity.dto.CapacityReport;
import com.bank.capacity.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class CapacityService {

    private final List<Employee> employees = List.of(
        new Employee("E001", "Rajesh Kumar",  "TRADING"),
        new Employee("E002", "Priya Sharma",  "RISK"),
        new Employee("E003", "Amit Patel",    "TRADING"),
        new Employee("E004", "Deepa Reddy",   "OPERATIONS"),
        new Employee("E005", "Vikram Singh",  "RISK"),
        new Employee("E006", "Neha Gupta",    "TRADING"),
        new Employee("E007", "Suresh Iyer",   "OPERATIONS"),
        new Employee("E008", "Kavita Joshi",  "RISK"),
        new Employee("E009", "Rohit Mehta",   "COMPLIANCE"),
        new Employee("E010", "Anita Desai",   "COMPLIANCE")
    );

    public CapacityReport generateReport() {

        // ═══ Step 1: Count per department ═══
        Map<String, Long> countByDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::department, TreeMap::new, Collectors.counting()));
        log.info("Headcount by dept: {}", countByDept);

        // ═══ Step 2: Largest department ═══
        String largest = countByDept.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(e -> e.getKey() + " (" + e.getValue() + " employees)")
            .orElse("No departments");
        log.info("Largest: {}", largest);

        // ═══ Step 3: Smallest department ═══
        String smallest = countByDept.entrySet().stream()
            .min(Map.Entry.comparingByValue())
            .map(e -> e.getKey() + " (" + e.getValue() + " employees)")
            .orElse("No departments");
        log.info("Smallest: {}", smallest);

        // ═══ Step 4: Ranked by size (descending) ═══
        List<String> ranked = countByDept.entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .map(e -> e.getKey() + ": " + e.getValue())
            .toList();
        log.info("Ranked: {}", ranked);

        // ═══ Step 5: Departments tied for largest ═══
        long maxCount = countByDept.values().stream()
            .mapToLong(Long::longValue).max().orElse(0);
        List<String> tied = countByDept.entrySet().stream()
            .filter(e -> e.getValue() == maxCount)
            .map(e -> e.getKey() + " (" + e.getValue() + ")")
            .toList();
        log.info("Tied for largest (count={}): {}", maxCount, tied);

        return new CapacityReport(countByDept, largest, smallest, ranked, tied);
    }
}
