package com.bank.capacity.service;

import com.bank.capacity.model.Employee;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class LargestDepartmentTest {

    List<Employee> emps = List.of(
        new Employee("E1", "A", "TRADING"),
        new Employee("E2", "B", "TRADING"),
        new Employee("E3", "C", "TRADING"),
        new Employee("E4", "D", "RISK"),
        new Employee("E5", "E", "RISK"),
        new Employee("E6", "F", "OPS")
    );

    @Test
    void findLargestDepartment() {
        String largest = emps.stream()
            .collect(Collectors.groupingBy(Employee::department, Collectors.counting()))
            .entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse("NONE");
        assertThat(largest).isEqualTo("TRADING");
    }

    @Test
    void findSmallestDepartment() {
        String smallest = emps.stream()
            .collect(Collectors.groupingBy(Employee::department, Collectors.counting()))
            .entrySet().stream()
            .min(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse("NONE");
        assertThat(smallest).isEqualTo("OPS");
    }

    @Test
    void rankedBySize() {
        List<String> ranked = emps.stream()
            .collect(Collectors.groupingBy(Employee::department, Collectors.counting()))
            .entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .map(Map.Entry::getKey)
            .toList();
        assertThat(ranked).containsExactly("TRADING", "RISK", "OPS");
    }

    @Test
    void findTiedDepartments() {
        List<Employee> tiedData = List.of(
            new Employee("1", "A", "X"), new Employee("2", "B", "X"),
            new Employee("3", "C", "Y"), new Employee("4", "D", "Y"),
            new Employee("5", "E", "Z")
        );
        Map<String, Long> counts = tiedData.stream()
            .collect(Collectors.groupingBy(Employee::department, Collectors.counting()));
        long maxCount = counts.values().stream().mapToLong(Long::longValue).max().orElse(0);
        List<String> tied = counts.entrySet().stream()
            .filter(e -> e.getValue() == maxCount)
            .map(Map.Entry::getKey).sorted().toList();
        assertThat(tied).containsExactly("X", "Y");  // both have 2
    }

    @Test
    void emptyReturnsOptionalEmpty() {
        Optional<Map.Entry<String, Long>> result = List.<Employee>of().stream()
            .collect(Collectors.groupingBy(Employee::department, Collectors.counting()))
            .entrySet().stream()
            .max(Map.Entry.comparingByValue());
        assertThat(result).isEmpty();
    }
}
